mkdir -p src/platform && cat > src/lib.rs <<'EOF'
//! Cross-platform library skeleton.
//!
//! Platform-specific code lives in `src/platform/`, one file per target
//! family. [`cfg_if::cfg_if!`] selects exactly one backend at compile time,
//! so the rest of the crate only ever sees a single, uniform API.

mod platform;

pub use platform::PLATFORM_NAME;

/// Returns a human-readable name for the platform this crate was built for.
pub fn platform_name() -> &'static str {
    PLATFORM_NAME
}

/// Returns the platform's native path separator.
pub fn path_separator() -> char {
    platform::path_separator()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn platform_name_is_not_empty() {
        assert!(!platform_name().is_empty());
    }

    #[test]
    fn separator_matches_std() {
        assert_eq!(path_separator(), std::path::MAIN_SEPARATOR);
    }
}
EOF
cat > src/platform/mod.rs <<'EOF'
//! Compile-time backend selection.
//!
//! Each backend module must expose the same items:
//! - `const PLATFORM_NAME: &str`
//! - `fn path_separator() -> char`
//!
//! Branches are checked top to bottom; the first match wins, so put more
//! specific predicates (e.g. `target_os = "macos"`) before broader ones
//! (e.g. `unix`).

cfg_if::cfg_if! {
    if #[cfg(windows)] {
        mod windows;
        pub use self::windows::*;
    } else if #[cfg(any(target_os = "macos", target_os = "ios"))] {
        mod apple;
        pub use self::apple::*;
    } else if #[cfg(target_os = "linux")] {
        mod linux;
        pub use self::linux::*;
    } else if #[cfg(all(target_family = "wasm", target_os = "unknown"))] {
        mod wasm;
        pub use self::wasm::*;
    } else if #[cfg(unix)] {
        mod unix;
        pub use self::unix::*;
    } else {
        compile_error!("platform_lib: unsupported target platform");
    }
}
EOF
gen() { cat > src/platform/$1.rs <<EOF
//! $2 backend.

pub const PLATFORM_NAME: &str = "$3";

pub fn path_separator() -> char {
    '$4'
}
EOF
}
gen windows "Windows" "windows" '\\'
gen apple "Apple (macOS / iOS)" "apple" '/'
gen linux "Linux" "linux" '/'
gen wasm "WebAssembly (wasm32-unknown-unknown)" "wasm" '/'
gen unix "Generic Unix (BSDs, illumos, etc.)" "unix" '/'
cat src/platform/windows.rs

